sparql:
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX pv: <http://ld.company.org/prod-vocab/>

SELECT ?bom ?avgPrice
WHERE {

  ?bom a pv:BillOfMaterial .
  ?part a pv:BomPart ;
         pv:hasSupplier ?supplier ;
         pv:price ?price .
  ?supplier a pv:Supplier ;
            pv:name ?name ;
            pv:addressCountry ?country .
  FILTER (?country = "United States" || ?country = "United Kingdom")
  OPTIONAL { ?part pv:width_mm ?width . }
  OPTIONAL { ?part pv:height_mm ?height . }
  OPTIONAL { ?part pv:depth_mm ?depth . }
  OPTIONAL { ?part pv:weight_g ?weight . }
  BIND((SUM(?price) / COUNT(DISTINCT ?part)) AS ?avgPrice)
}
GROUP BY ?bom
HAVING (AVG(?avgPrice) = MAX(?avgPrice))

